def blob(path):
    r = subprocess.run(['git', 'cat-file', 'blob', '%s:%s' % (REF, path)], capture_output=True)
    return r.stdout if r.returncode == 0 else None
def tree(prefix):
    r = subprocess.run(['git', '-c', 'core.quotepath=false', 'ls-tree', '-r', '--name-only', REF, '--', prefix], capture_output=True, text=True)
    return [l for l in r.stdout.split('\n') if l]
def pl(s): return [] if not s else (['*'] if s == '*' else s.split(','))
def put(data, targets):
    """Пишет файл в первую папку и делает жёсткие ссылки в остальные."""
    first = None
    for t in targets:
        os.makedirs(os.path.dirname(t), exist_ok=True)
        if os.path.exists(t): os.remove(t)
        if first is None:
            with open(t + '.part', 'wb') as f: f.write(data)
            os.replace(t + '.part', t); first = t
        else: os.link(first, t)
def pdf_info(data):
    if data[:4] != b'%PDF': return 0, ''
    try:
        d = fitz.open(stream=data, filetype='pdf'); n = d.page_count
        t = ' '.join(d[i].get_text() for i in range(min(3, n))); d.close(); return n, t
    except Exception: return 0, ''
def run():
    cand = json.load(open(os.path.join(HERE, 'sci_cand.json'), encoding='utf-8'))
