    # --- издания библиотеки
    for i, x in enumerate(cand):
        if i in REJ: continue
        v = DEC[i]; cat, g, s, au, title, kind, what, pub, year = v[:9]; yname = v[9] if len(v) > 9 else year
        data = blob('.work/sci4/%s.pdf' % x['n'])
        if not data: st['нет файла издания'] += 1; print('НЕТ ФАЙЛА', i, x['n']); continue
        pages, text = pdf_info(data)
        if not pages or len(re.findall('[а-яё]', text.lower())) < 200: st['брак издания'] += 1; print('БРАК', i, x['n'], pages); continue
        if cat == 'sci' and kind == 'журнал':
            name = '%s. Журнал. %s. %s.pdf' % (title, yname, pub)
        else:
            name = LP.make_name(dict(kind=kind, pub=pub, year=year, authors=au, title=title), set())
        ds = [d for d, p in (('g', g), ('s', s)) if p]
        for d in ds:
            base, k = name, 2
            while name.lower() in taken[d][cat]: name = base[:-4] + ' (%d).pdf' % k; k += 1
        for d in ds: taken[d][cat].add(name.lower())
        put(data, [os.path.join(ROOT, DISC[d], FOLDER[cat], name) for d in ds])
        man.append(dict(key=x['n'], cat=cat, authors=au, title=title, kind=kind, what=what, pub=pub, year=year, pages=pages, size=len(data), sha=hashlib.sha256(data).hexdigest(),
                        name=name, g=pl(g), s=pl(s), url=x['url'], origin=LIBNOTE)); st['изданий'] += 1
