        if name.endswith('.pdf'):
            pages, text = pdf_info(data)
            if not pages: st['брак эмпирического'] += 1; print('БРАК', fn); continue
        else:
            pages = 0
            if data[:8] != bytes.fromhex('D0CF11E0A1B11AE1') and data[:2] != b'PK': st['брак эмпирического'] += 1; print('НЕ XLS', fn, data[:60]); continue
